$sales = @(
    [pscustomobject]@{ Region = 'North'; Target = 120000; Actual = 131500 }
    [pscustomobject]@{ Region = 'South'; Target = 95000; Actual = 94100 }
    [pscustomobject]@{ Region = 'East'; Target = 110000; Actual = 82300 }
    [pscustomobject]@{ Region = 'West'; Target = 105000; Actual = 106200 }
)

New-OfficeWord -Path .\Reports\Q3-Sales.docx {
    WordHeading 'Q3 sales by region'
    WordTable -InputObject $sales {
        WordTableCondition { $_.Actual -ge $_.Target * 1.05 } -BackgroundColor Success
        WordTableCondition { $_.Actual -lt $_.Target * 0.9 } -BackgroundColor Danger
        WordTableCondition { $_.Actual -lt $_.Target -and $_.Actual -ge $_.Target * 0.9 } -BackgroundColor '#FEF3C7'
    }
}

New-OfficeWord -Path .\Reports\Patch.docx {
    WordTable -InputObject $servers -Property Name, Compliance -ColumnFormat @{ Compliance = 'P1' } {
        WordTableCondition { $_.Compliance -lt 0.8 } -Column Compliance -BackgroundColor Danger
        WordTableCondition { $_.Compliance -lt 0.95 } -Column Compliance -BackgroundColor Warning
        WordTableCondition { $_.Compliance -ge 0.95 } -Column Compliance -BackgroundColor Success
    }
}

